// FAIL CLOSED on the token. This endpoint blocks an agent run and pages a human,
// so an unauthenticated caller on the docker network could spend a person's
// attention on demand.
//
// This node returns a VERDICT, it does not throw. The webhook answers with the
// verdict's status (responseMode "responseNode"), so the CALLER learns whether it
// was let in. It used to throw here behind an onReceived webhook that had
// already answered 200 "Workflow was started" to everyone: a wrong token, the
// runners' own token and no token all got 200, and only n8n's log knew. The seam
// heartbeat could not tell a locked door from an open one, and ask-human-mcp told
// an unauthorised agent its question had been raised. A refusal still raises the
// alarm: "Raise the alarm" throws after the refusal is answered.
//
//   401  missing or wrong x-ask-human-token
//   503  n8n itself has no ASK_HUMAN_TOKEN, so it refuses everything
//   400  authenticated, but the request is not one we can act on
//   200  authenticated liveness probe (asks nobody)
//   202  authenticated question, accepted; a human is being asked
const req = $input.first().json || {};
const headers = req.headers || {};
const want = $env.ASK_HUMAN_TOKEN || '';
const got = headers['x-ask-human-token'] || headers['X-Ask-Human-Token'] || '';
const refuse = (status, reason) => [{ json: { status, ok: false, reason } }];

if (!want) {
  return refuse(503, 'ask-webhook: ASK_HUMAN_TOKEN is not set in n8n — refusing to serve an unauthenticated question endpoint.');
}
if (!got || got !== want) {
  return refuse(401, 'ask-webhook: bad or missing x-ask-human-token');
}

const b = req.body || {};

// LIVENESS PROBE. `{ "healthcheck": true }` returns without asking anyone
// anything. It exists because the only way to prove this door is OPEN is to
// knock on it, and a probe that pages a human every 15 minutes is worse than no
// probe at all.
//
// AUTH IS CHECKED FIRST, above, deliberately. A healthcheck branch that skipped
// the token would hand anything on the docker network a free way to confirm this
// endpoint exists — reconnaissance on the one seam that spends human attention.
//
// It also succeeds CLEANLY rather than throwing: a failed execution trips the
// Global Error Handler, so a probe built on a deliberate error would alert on
// every run and teach everyone to ignore the alert.
if (b.healthcheck === true) {
  return [{ json: { status: 200, ok: true, healthcheck: true } }];
}

const question = (b.question || '').trim();
if (!question) {
  return refuse(400, 'ask-webhook: `question` is required — refusing to ask a human nothing.');
}

// The ticket is a KEY, and keys from callers deserve an allowlist rather than a
// sanitiser. UUID or nothing.
const ticket = String(b.ticket || '').trim();
if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(ticket)) {
  return refuse(400, 'ask-webhook: `ticket` must be a UUID.');
}

// Bound the wait: the agent is blocked while this runs.
const MAX_MIN = 10;
const minutes = Math.min(Number(b.timeoutMinutes) > 0 ? Number(b.timeoutMinutes) : MAX_MIN, MAX_MIN);

return [{ json: {
  status: 202, ok: true, healthcheck: false,
  ticket, question,
  context: b.context || '',
  source: b.source || 'agent',
  timeoutHours: minutes / 60,
} }];

// Shape the answer for delivery. `answered` stays separate from `answer` all the
// way to the agent: "nobody answered" and "answered with nothing" are different
// facts, and a caller that cannot tell them apart treats silence as data.
const a = $input.first().json || {};
const t = $('Authenticate + validate').first().json || {};
return [{ json: {
  ticket: t.ticket,
  provider: 'claude',
  answered: a.answered === true,
  answer: a.answer || '',
  timedOut: a.timedOut === true,
  note: a.note || '',
} }];

// The refusal has already been ANSWERED (so the caller sees 4xx/5xx). Throwing
// now hands the reason to the Global Error Handler, which is how a wrong or
// missing token has always been reported. Making the status visible must not
// quietly drop that signal: an unknown caller knocking on the door that pages a
// human is worth knowing about.
const v = $input.first().json || {};
throw new Error(v.reason || `ask-webhook: refused with HTTP ${v.status}`);
